{
  "strategy_name": "daily_double_sma_trend",
  "description": "A daily timeframe trend-following strategy that enters when the 20-period simple moving average crosses above the 60-period simple moving average and exits on a cross below.",
  "version": "1.0",
  "market": {
    "symbol": "SPY",
    "timeframe": "1d",
    "start_date": "2020-01-01",
    "end_date": "2024-12-31"
  },
  "indicators": [
    {"name": "SMA", "params": {"window": 20}, "alias": "sma_20"},
    {"name": "SMA", "params": {"window": 60}, "alias": "sma_60"}
  ],
  "entry_rules": [
    {"type": "cross_over", "left": "sma_20", "right": "sma_60"}
  ],
  "exit_rules": [
    {"type": "cross_under", "left": "sma_20", "right": "sma_60"}
  ],
  "risk_control": {
    "position_size": 0.5,
    "stop_loss": 0.1,
    "take_profit": null,
    "max_drawdown_limit": 0.2,
    "allow_short": false,
    "leverage": 1.0
  }
}

